def partition(s):
    n = len(s)
    result = []
    path = []

    def is_palindrome(sub):
        return sub == sub[::-1]

    def backtrack(start):
        if start == n:
            result.append(path[:])
            return
        for end in range(start + 1, n + 1):
            piece = s[start:end]
            if is_palindrome(piece):
                path.append(piece)
                backtrack(end)
                path.pop()

    backtrack(0)
    result.sort(key=lambda partition_list: tuple(partition_list))
    return result

